// A container that returns a reference from operator[]
std::vector<std::string> names = {"Alice", "Bob"};

// This function perfectly forwards the return type of operator[]
// If names[i] returns string&, this function returns string&
decltype(auto) getName(int i)
{
  return names[i];
}

// Using auto would return a copy (a std::string), not a reference
auto getNameCopy(int i)
{
  return names[i];
}

// Usage:
getName(0) = "Alicia"; // Works: modifies the element in the vector
// getNameCopy(1) = "Robert"; // Error: returns a temporary copy (prvalue)
